import {coreArt,wordArt} from './story-art.mjs';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function getStoryWord(data,name){
 const w=data.words.find(w=>w.word===name),edit=data.editorial.words[name];
 if(!w||!w.quiz_eligible||edit?.use!=='quiz')throw Error('Story vocabulary is not approved: '+name);
 return {...w,meaning_ja:edit.meaning_ja||w.meaning_ja,base_hint_ja:edit.base_hint_ja};
}
const audio=(word,label='聞く')=>`<button class="story-audio" data-action="speak" data-word="${escape(word)}" aria-label="${escape(word)}の発音を聞く">♪ ${label}</button>`;
function wordLabel(w,story){const pre=story.form.replace(/-$/,'');return `<span class="story-formed" lang="en"><span class="word-prefix">${escape(pre)}</span><span>${escape(w.base)}</span></span>`;}
export function coreCard(story,{compact=false}={}){
 return `<section class="image-core ${compact?'core-compact':''}" data-motion-card data-core="${escape(story.prefix_id)}"><div class="core-copy"><div class="eyebrow">ことばのレンズ</div><h1><span lang="en">${escape(story.form)}</span><small>${escape(story.cue_ja)}</small></h1><p class="core-title">${escape(story.title_ja)}</p><div class="story-controls"><button data-story-action="replay" class="primary">動きをもう一度</button><button data-story-action="narrate" data-prefix="${escape(story.prefix_id)}">♪ 先生のお話</button></div><p class="story-stage-label" aria-live="polite">これから動きます</p></div><div class="core-picture">${coreArt(story.image,story.form,story.title_ja)}</div></section>`;
}
function exampleCard(entry,story,data,index){const w=getStoryWord(data,entry.word);return `<article class="story-example" data-motion-card data-example="${escape(w.word)}"><div class="example-top"><span class="story-number">${index+1}</span><span class="mini-lens">${escape(story.form)} <span>${escape(story.cue_ja)}</span></span></div><div class="picture-stage">${wordArt(entry.scene,`${w.base}：${w.base_hint_ja}。${w.word}：${w.meaning_ja}`)}</div><div class="example-caption"><div class="base-caption"><span lang="en">${escape(w.base)}</span> <span>${escape(w.base_hint_ja)}</span>${audio(w.base)}</div><div class="formed-caption">${wordLabel(w,story)}${audio(w.word)}<span class="whole-meaning">${escape(w.meaning_ja)}</span></div></div><div class="story-controls compact-controls"><button data-story-action="replay">もう一度見る</button><button data-story-action="before" aria-pressed="false">元の絵を見る</button></div></article>`;}
export function storyPage(story,data,{next=null,stage=1}={}){
 const transfer=story.transfer,w=transfer?getStoryWord(data,transfer.word):null;
 return `<div class="story-page" data-story-reader="${escape(story.prefix_id)}"><div class="reader-nav"><a href="#images">← イメージの本だな</a><label><input id="story-motion" type="checkbox"> 動きを減らす</label></div>${coreCard(story)}<div class="reader-section-title"><span>同じレンズで、単語を見てみよう。</span><small>ゆっくり下へ。絵が一度だけ動きます。</small></div><section class="story-examples ${story.examples.length===1?'single-example':''}">${story.examples.map((e,i)=>exampleCard(e,story,data,i)).join('')}</section>${w?`<section class="story-transfer" data-transfer><div class="transfer-copy"><div class="eyebrow">このレンズ、別の語にも使える？</div><h2 lang="en">${escape(w.word)}</h2><p><span lang="en">${escape(w.base)}</span> は「${escape(w.base_hint_ja)}」${audio(w.base)}</p><button class="primary" data-story-action="reveal">絵でたしかめる</button><p class="transfer-answer" hidden aria-live="polite">${escape(w.meaning_ja)} ${audio(w.word)}</p></div><div class="transfer-picture" data-motion-card data-hidden-transfer><div class="picture-stage" aria-hidden="true">${wordArt(transfer.scene,`${w.word}：${w.meaning_ja}`)}</div><div class="picture-curtain" aria-hidden="true">？</div></div></section>`:`<p class="story-bottom-note">bi-では「何が2つ？」を、主翼の絵で確かめよう。単語を自由に組み合わせて増やしません。</p>`}<details class="story-scope"><summary>先生から、ひとこと</summary><p>${escape(story.scope_ja)}</p><p class="muted">この絵は意味を考えるための手がかりです。語源の万能な図ではありません。教材は暫定版です。</p></details><div class="reader-finish"><div><strong>「この見方、ほかでも使えそう！」</strong><p>お話を読むだけで進めます。確認問題は、ためしたいときに。</p></div><div class="actions">${next?`<a class="button primary" href="#lesson/${escape(next.prefix_id)}">次のお話 ${escape(next.form)} →</a>`:'<a class="button primary" href="#images">本だなへ →</a>'}<button data-action="practice" data-prefix="${escape(story.prefix_id)}">問題でもためす</button></div></div><details class="story-scope"><summary>登録されている他の語と、レビュー対象を見る</summary>${data.words.filter(x=>x.prefix_id===story.prefix_id).map(x=>{const e=data.editorial.words[x.word];return `<div class="review-row"><strong lang="en">${escape(x.word)}</strong> ${audio(x.word)}<p>${escape(x.split)} → ${escape(e?.meaning_ja||x.meaning_ja)}</p>${e?.use==='card'?`<p class="warning">説明カード・要レビュー（出題しません）：${escape(e.reason_ja)}</p>`:''}</div>`;}).join('')}</details></div>`;
}
export function storyShelf(stories,seen=[]){return `<div class="image-shelf">${stories.map(s=>`<a class="image-book" href="#lesson/${escape(s.prefix_id)}"><div class="image-book-art is-applied" aria-hidden="true">${coreArt(s.image,s.form,s.title_ja)}</div><div class="image-book-title"><strong lang="en">${escape(s.form)}</strong><span>${escape(s.cue_ja)}</span></div><span class="image-book-footer">${seen.includes(s.prefix_id)?'イメージを見た':'お話をひらく'} →</span></a>`).join('')}</div>`;}
